mapper.select:
select id, log_type, user_id, username, result, user_ip, user_agent, create_time from system_login_log sll where delete_flag = 0
and user_ip like concat('%', #{request.userIp}, '%')
and username like concat('%', #{request.username}, '%')
and result = #{request.status.value}
and create_time >= #{request.createTimeBegin}
and create_time <= #{request.createTimeEnd}
order by create_time desc
